def to_dict(self):
    """Return a dictionary containing all five version parts.

    The keys are major, minor, patch, prerelease, and build.

    :rtype: dict
    """
    return self._asdict()

def __getitem__(self, index):
    """Return version parts by integer index or slice, as for a tuple.

    Parts are ordered as major, minor, patch, prerelease, and build.
    Negative indices count from the end; slices return tuples.
    """
    return self.to_tuple()[index]

